dashboard.definition:
{
  "title": "Environment Health",
  "description": "Cross-cutting operational view \u2014 KPIs, error trends by category, critical events, and host health matrix",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          },
          {
            "label": "DNS Analytics",
            "value": "logserv_dns_analytics"
          },
          {
            "label": "HANA Audit",
            "value": "logserv_hana_audit"
          },
          {
            "label": "HANA Trace",
            "value": "logserv_hana_trace"
          },
          {
            "label": "Web Dispatcher",
            "value": "logserv_web_dispatcher"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "ABAP Operations",
            "value": "logserv_abap_operations"
          },
          {
            "label": "SAP Services",
            "value": "logserv_sap_services"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Linux",
            "value": "logserv_linux"
          },
          {
            "label": "Windows",
            "value": "logserv_windows"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "SAP Router",
            "value": "logserv_sap_router"
          },
          {
            "label": "Work Process Performance",
            "value": "logserv_work_process_performance"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_kpi_total_errors": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_total_errors"
      },
      "title": "Total Errors",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/search?q=index%3Dsap_logserv_logs%20%28%28sourcetype%3D%22sap%3Aabap%3Adispatcher%22%20%28dp_severity%3D%22ERROR%22%20OR%20dp_severity%3D%22FATAL%22%29%29%20OR%20%28sourcetype%3D%22sap%3Aabap%3Aicm%22%20icm_is_error%3D1%29%20OR%20%28sourcetype%3D%22sap%3Aabap%3Agateway%22%20gw_error_detail%21%3D%22%22%29%20OR%20%28sourcetype%3D%22sap%3Ahana%3Aaudit%22%20status%21%3D%22SUCCESSFUL%22%29%20OR%20%28sourcetype%3D%22sap%3Ahana%3Atracelogs%22%20%28hana_trace_severity%3D%22error%22%20OR%20hana_trace_severity%3D%22fatal%22%29%29%20OR%20%28sourcetype%3D%22sap%3Ascc%3Ahttp_access%22%20is_error%3D%22true%22%29%20OR%20%28sourcetype%3D%22sap%3Asapstartsrv%22%20is_auth_event%3D%22true%22%20auth_result%3D%22failure%22%29%20OR%20%28sourcetype%3D%22sap%3Asaprouter%22%20is_error%3D%22true%22%29%20OR%20%28sourcetype%3D%22sap%3Awebdispatcher%3Aaccess%22%20status%3E%3D400%29%20OR%20%28sourcetype%3D%22XmlWinEventLog%22%20%28severity%3D%22high%22%20OR%20severity%3D%22medium%22%29%29%20OR%20%28sourcetype%3D%22linux_secure%22%20IN_DROP%29%20OR%20%28sourcetype%3D%22squid%3Aaccess%22%20action%3D%22denied%22%29%29%20%7C%20eval%20Category%3Dcase%28match%28sourcetype%2C%22sap%3Aabap%22%29%2C%22ABAP%22%2Cmatch%28sourcetype%2C%22sap%3Ahana%22%29%2C%22HANA%22%2Csourcetype%20IN%20%28%22sap%3Asapstartsrv%22%2C%22sap%3Ascc%3Ahttp_access%22%2C%22linux_secure%22%29%2C%22Security%22%2Csourcetype%20IN%20%28%22sap%3Awebdispatcher%3Aaccess%22%2C%22sap%3Asaprouter%22%2C%22squid%3Aaccess%22%29%2C%22Web%2FNetwork%22%2Csourcetype%3D%22XmlWinEventLog%22%2C%22OS%2FInfra%22%2C1%3D1%2C%22Other%22%29%20%7C%20stats%20count%20as%20Errors%20dc%28host%29%20as%20%22Affected%20Hosts%22%20latest%28_time%29%20as%20lt%20by%20Category%20sourcetype%20%7C%20eval%20%22Last%20Seen%22%3Dstrftime%28lt%2C%22%25Y-%25m-%25d%20%25H%3A%25M%22%29%20%7C%20fields%20-%20lt%20%7C%20sort%20-Errors&earliest=$global_time.earliest$&latest=$global_time.latest$&display.page.search.mode=verbose&display.general.type=statistics",
            "newTab": true
          }
        }
      ]
    },
    "viz_kpi_hana_failures": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_hana_failures"
      },
      "title": "HANA Failed Ops",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_hana_audit?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_auth_failures": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_auth_failures"
      },
      "title": "Auth Failures",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_sap_services?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_firewall_drops": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_firewall_drops"
      },
      "title": "Firewall Drops",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_linux?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_web_error_rate": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_web_error_rate"
      },
      "title": "Web Error Rate %",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "unitLabel": "%",
        "unitPosition": "after"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_web_dispatcher?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_beaconing": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_beaconing"
      },
      "title": "Beaconing Domains",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_dns_analytics?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_err_abap": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_err_abap"
      },
      "title": "ABAP Error Trend",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "Dispatcher": "#b50101",
          "ICM": "#ff7a6b",
          "Gateway": "#dc4e41"
        },
        "dataValuesDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_abap_security?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_err_hana": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_err_hana"
      },
      "title": "HANA Error Trend",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "Audit Failures": "#dc4e41",
          "Trace Errors": "#ff7a6b"
        },
        "dataValuesDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_hana_audit?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_err_security": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_err_security"
      },
      "title": "Security Error Trend",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "Auth Failures": "#b50101",
          "Firewall Drops": "#dc4e41"
        },
        "dataValuesDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_sap_services?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_err_webnet": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_err_webnet"
      },
      "title": "Web/Network Error Trend",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "WebDisp 4xx/5xx": "#0877a6",
          "Router Errors": "#4fa484",
          "Proxy Denied": "#6cb4d9"
        },
        "dataValuesDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_web_dispatcher?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_err_osinfra": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_err_osinfra"
      },
      "title": "OS/Infra Error Trend",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "Windows High": "#7b56db",
          "Windows Medium": "#a88ad4"
        },
        "dataValuesDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_windows?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_err_scc": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_err_scc"
      },
      "title": "Cloud Connector Error Trend",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "4xx Client": "#f1813f",
          "5xx Server": "#dc4e41"
        },
        "dataValuesDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_cloud_connector?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_rect_r2b_scc": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_critical_events": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_critical_events"
      },
      "title": "Recent Critical Events",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "splunk_app_sap_logserv",
            "dashboard": "logserv_host_details",
            "newTab": false,
            "tokens": [
              {
                "token": "host_name",
                "value": "row.Host.value"
              },
              {
                "token": "global_time.earliest",
                "value": "$global_time.earliest$"
              },
              {
                "token": "global_time.latest",
                "value": "$global_time.latest$"
              }
            ]
          }
        }
      ]
    },
    "viz_top_hosts": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_top_hosts"
      },
      "title": "Top Affected Hosts",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "splunk_app_sap_logserv",
            "dashboard": "logserv_host_details",
            "newTab": false,
            "tokens": [
              {
                "token": "host_name",
                "value": "row.Host.value"
              },
              {
                "token": "global_time.earliest",
                "value": "$global_time.earliest$"
              },
              {
                "token": "global_time.latest",
                "value": "$global_time.latest$"
              }
            ]
          }
        }
      ]
    },
    "viz_web_response_time": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_web_response_time"
      },
      "title": "Web Dispatcher Response Time",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColors": [
          "#f1813f"
        ],
        "dataValuesDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_web_dispatcher?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_icm_status": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_icm_status"
      },
      "title": "ICM Status Codes",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "2xx": "#4fa484",
          "3xx": "#0877a6",
          "4xx": "#dc4e41",
          "5xx": "#f1813f"
        },
        "dataValuesDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_abap_security?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_pipeline_health": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_pipeline_health"
      },
      "title": "Data Pipeline \u2014 Events/Day",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_overview?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_pipeline_trend": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_pipeline_trend"
      },
      "title": "Daily Event Volume Trend",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColors": [
          "#4fa484"
        ],
        "dataValuesDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/logserv_overview?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_rect_r2a_left": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r2a_mid": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r2a_right": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r2b_left": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r2b_right": {
